                .isEqualTo(409);
        assertThat(confirm("dave", moveKey, uniqueKey("CMD")).getResponse().getStatus())
                .isEqualTo(409);
    }

    @Test
    void confirmWithDisabledTargetReturns409() throws Exception {
        String[] fixture = prepareMoveFixture();
        String moveKey = uniqueKey("MOVE");
